<script setup>
import { inject, proxyRefs, reactive } from 'vue';
import { useController } from '../../components/admin/AdminVotingSettings.vue?admin-v2-controller';
import V2Panel from '../components/shared/V2Panel.vue';
import V2Icon from '../components/shared/V2Icon.vue';
import ClosureSummary from '../components/dashboard/ClosureSummary.vue';
const props=defineProps({settings:Boolean});const c=inject('admin-v2');
const controllerProps=reactive({get authHeaders(){return c.authHeaders;},get organizationSlug(){return c.organizationSlug;}});
